package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderRec OrderRec
var orderFile *os.File
var orderReader *bufio.Reader
var inputDone bool

func main() {
	MAINPARA()
}

func MAINPARA() {
	var err error
	orderFile, err = os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty
		orderFile = nil
		orderReader = nil
	} else {
		orderReader = bufio.NewReader(orderFile)
	}
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	if orderFile != nil {
		orderFile.Close()
	}
	SUMMARYPARA()
}

func READPARA() {
	if orderReader == nil {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line, err := orderReader.ReadString('\n')
	if err != nil {
		// EOF
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	// strip trailing \n and \r
	line = strings.TrimRight(line, "\r\n")
	// pad with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// parse
	orderRec.OrId = line[0:5]
	orderRec.OrStat = line[5:6]
	orderRec.OrQty = parseInt(line[6:9])
	orderRec.OrPrice = parsePrice(line[9:15])
}

func parseInt(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	fmt.Sscanf(s, "%d", &v)
	return v
}

func parsePrice(s string) decimal.Decimal {
	// 6 digits, implied 2 decimals
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	var n int64
	fmt.Sscanf(s, "%d", &n)
	return decimal.New(n, -2)
}

func PROCESSPARA() {
	WsTotal = decimal.Zero
	// EVALUATE TRUE
	if orderRec.OrQty == 0 {
		WsBadQty++
		// DISPLAY OR-ID " BAD QTY"
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
	} else if orderRec.OrStat == "N" {
		WsTotal = decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice)
		WsTotal = truncateToScale(WsTotal, 2)
		WsTotal = keepLowOrder(WsTotal, 8, 2)
		WsNewCount++
		SHOWPARA()
	} else if orderRec.OrStat == "S" {
		// COMPUTE ROUNDED = qty * price * 1.05
		v := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice).Mul(decimal.NewFromFloat(1.05))
		WsTotal = v.Round(2)
		WsTotal = keepLowOrder(WsTotal, 8, 2)
		WsShipCount++
		SHOWPARA()
	} else if orderRec.OrStat == "C" {
		WsCancelCount++
		SHOWPARA()
	} else {
		WsInvalid++
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	WsGrand = keepLowOrder(WsGrand, 10, 2)
	READPARA()
}

func truncateToScale(d decimal.Decimal, scale int32) decimal.Decimal {
	return d.Truncate(scale)
}

func keepLowOrder(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// keep low-order digits that fit: for integer part capacity
	// compute 10^intDigits as decimal
	mod := decimal.New(1, int32(intDigits)) // 10^intDigits
	// separate sign?
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	// integer part truncated already
	// To drop high-order digits: integerPart mod 10^intDigits plus fractional part
	// d = intPart + frac
	// frac = d - intPart
	// Use: d Mod mod via integer arithmetic on scaled value
	// scale factor = 10^scale
	factor := decimal.New(1, scale)
	scaled := d.Mul(factor) // integer scaled
	// scaledInt is integer
	// we want scaled mod (mod*factor)
	modScaled := mod.Mul(factor)
	// decimal.Mod ?
	// Use Div + truncate
	// scaled - trunc(scaled / modScaled)*modScaled
	if scaled.GreaterThanOrEqual(modScaled) || scaled.GreaterThanOrEqual(decimal.NewFromInt(0)) && scaled.Cmp(modScaled) >= 0 {
		q := scaled.Div(modScaled).Truncate(0)
		scaled = scaled.Sub(q.Mul(modScaled))
		d = scaled.Div(factor)
		if neg {
			d = d.Neg()
		}
		return d
	}
	if neg {
		d = d.Neg()
	}
	return d
}

func SHOWPARA() {
	WsQtyEd = formatEdited(decimal.NewFromInt(orderRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(orderRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SUMMARYPARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	// counts are PIC 99 zero-padded 2
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", fmtInt(WsNewCount, 2), fmtInt(WsShipCount, 2), fmtInt(WsCancelCount, 2))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", fmtInt(WsInvalid, 2), fmtInt(WsBadQty, 2))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func fmtInt(v int64, w int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) > w {
		s = s[len(s)-w:]
	} else if len(s) < w {
		s = strings.Repeat("0", w-len(s)) + s
	}
	return s
}

func formatEdited(d decimal.Decimal, pic string) string {
	// determine scale = digits after '.'
	dotIdx := strings.Index(pic, ".")
	scale := 0
	if dotIdx != -1 {
		for _, c := range pic[dotIdx+1:] {
			if c == '9' || c == 'Z' {
				scale++
			}
		}
	}
	// capacity integer digits
	intPic := pic
	if dotIdx != -1 {
		intPic = pic[:dotIdx]
	}
	capacity := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			capacity++
		}
	}
	// fractional digits count = scale
	// get sign
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	d = d.Truncate(int32(scale))
	// integer part
	factor := decimal.New(1, int32(scale))
	scaled := d.Mul(factor).Truncate(0)
	// scaled is integer value of (intPart*10^scale + frac)
	fracInt := int64(0)
	intPart := int64(0)
	if scale > 0 {
		mod := int64(1)
		for i := 0; i < scale; i++ {
			mod *= 10
		}
		// scaled fits in int64 for these sizes
		sv := scaled.IntPart()
		fracInt = sv % mod
		intPart = sv / mod
	} else {
		intPart = scaled.IntPart()
	}
	// drop high-order digits: intPart mod 10^capacity
	if capacity > 0 {
		mod := int64(1)
		for i := 0; i < capacity; i++ {
			mod *= 10
		}
		// careful overflow capacity up to 10 -> 10^10 fits in int64
		intPart = intPart % mod
	}
	// build integer digits array of length capacity
	digits := make([]byte, capacity)
	tmp := intPart
	for i := capacity - 1; i >= 0; i-- {
		digits[i] = byte(tmp % 10)
		tmp /= 10
	}
	// Build output
	out := make([]byte, len(pic))
	// Need to know placeholder positions
	// Suppression handling for integer part
	// Determine index of digit cursor
	digitIdx := 0
	// Determine the position of the last Z? For suppression: any leading Z zeros become spaces.
	// Suppression ends at first non-zero digit encountered (among Z positions) OR at a '9' placeholder.
	// We can simulate: iterate over pic's integer section left to right, tracking if still suppressing.
	suppress := true
	// For integer section, we need to map digits to placeholders in order.
	// Create placeholder index mapping
	for i, ch := range pic {
		if ch == '.' {
			out[i] = '.'
			// suppression ends before dot? Actually spaces already handled; dot stays dot
			// but in COBOL, dot is always shown? For integer zero, we want to keep dot.
			// suppression flag no longer matters after dot.
			suppress = false
		} else if ch == ',' {
			// comma: if still suppressing -> space else comma
			if suppress {
				// check if all remaining Z placeholders are still zero? Simpler: if suppress currently, comma becomes space
				// But if later non-zero appears, earlier commas should have been spaces (which they are)
				out[i] = ' '
			} else {
				out[i] = ','
			}
		} else if ch == 'Z' || ch == '9' {
			// only for integer part before dot, digitIdx maps
			if dotIdx != -1 && i > dotIdx {
				// fractional part
				// fractional digits are after dot in order
				fracPos := 0
				// count how many fractional placeholders before this position
				for k := dotIdx + 1; k < i; k++ {
					if pic[k] == 'Z' || pic[k] == '9' {
						fracPos++
					}
				}
				// get frac digit
				// fracInt has scale digits, leftmost is most significant
				div := int64(1)
				for k := 0; k < scale-fracPos-1; k++ {
					div *= 10
				}
				d := byte((fracInt / div) % 10)
				out[i] = '0' + d
			} else {
				// integer part
				d := digits[digitIdx]
				digitIdx++
				if ch == 'Z' && suppress && d == 0 {
					// check if this is the last integer placeholder? Actually if all integer digits are zero, the last Z before dot should still suppress to space? But spec: Z suppression leaves one zero before dot if entire integer is zero? With picture ZZ9, zero should show as "  0"? Let's see: Z suppresses leading zero -> space, but the 9 always shows. So final 9 will show 0.
					// So we need to look ahead: if all remaining integer placeholder digits are zero and all are Z except final 9? The above logic handles because '9' will break suppression.
					out[i] = ' '
				} else {
					// if ch is '9', suppression ends
					// if ch is 'Z' and non-zero, suppression ends
					if ch == 'Z' && d != 0 {
						suppress = false
					} else if ch == '9' {
						suppress = false
					}
					// but if we are still suppressing and ch is Z with zero, we already handled; if suppress and ch==Z with zero we spaced, still suppress
					// if we reach here, we output digit
					if out[i] == 0 { // not set
						out[i] = '0' + d
					} else {
						// already set? shouldn't
						out[i] = '0' + d
					}
					if suppress && ch == '9' {
						// shouldn't happen, but '9' with zero should show zero
						suppress = false
					}
				}
				// if we printed a non-space, commas before next? suppression flag updated
				// need to update suppression for future commas: if we printed a digit (including zero from 9), suppression ends
				if out[i] != ' ' {
					suppress = false
				}
			}
		} else {
			out[i] = byte(ch)
		}
	}
	// Handle case integer all suppress spaces -> need to ensure commas already spaces
	_ = neg
	return string(out)
}
